import {POST_RECIPIENTS,POST_TEMPLATES} from './postcards.js';
const $=s=>document.querySelector(s);
export function openPostOffice({ui,getProgress,transact}){let recipient='chinchilla',template='hello';return ui.workshop('마음 우체국 · 안부 한 장',`<p class="village-note">게임 속 친구에게만 전해지는 편지예요. 실제 이메일이나 메시지는 보내지 않아요.</p><h3>받을 친구</h3><div class="choice-row">${Object.entries(POST_RECIPIENTS).map(([id,r])=>`<button data-recipient="${id}">${r.name}</button>`).join('')}</div><h3>전할 마음</h3><div class="choice-row">${Object.entries(POST_TEMPLATES).map(([id,t])=>`<button data-template="${id}">${t.label}</button>`).join('')}</div><section class="postcard-sheet"><p id="post-to"></p><p id="post-text"></p><p class="post-signature">도름이가</p></section><label class="gift-choice"><input type="checkbox" id="post-gift"> 카페에서 만든 케이크 1개 함께 보내기</label><p id="post-stock"></p><button id="post-send" class="primary">마을 우편함에 넣기</button><p id="post-result" role="status" aria-live="polite"></p><h3>도착한 답장</h3><div id="post-replies" class="choice-row"></div><section class="postcard-sheet" id="post-reply" hidden></section><p class="caption">친구마다 세 가지 마음을 한 번씩 보낼 수 있어요. 답장과 받은 책갈피는 이 브라우저에 저장돼요.</p>`,()=>{let alive=true;function render(){const s=getProgress().village,b=s.bakery,sent=s.mailbox.letters.some(l=>l.id===recipient+'.'+template);$('#post-to').textContent=POST_RECIPIENTS[recipient].name+'에게 · '+POST_RECIPIENTS[recipient].role;$('#post-text').textContent=POST_TEMPLATES[template].text;document.querySelectorAll('[data-recipient]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.recipient===recipient)));document.querySelectorAll('[data-template]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.template===template)));$('#post-gift').disabled=b.pastries<1||sent;if($('#post-gift').disabled)$('#post-gift').checked=false;$('#post-stock').textContent=`보관 중인 케이크 ${b.pastries}개 · 선물을 전하면 친구가 작은 책갈피를 답장에 넣어 줘요`;$('#post-send').disabled=sent;$('#post-send').textContent=sent?'이미 전한 마음이에요':'마을 우편함에 넣기';$('#post-replies').innerHTML=s.mailbox.letters.map(l=>`<button data-reply="${l.id}">${l.read?'읽은 편지':'새 답장'} · ${POST_RECIPIENTS[l.recipient].name}${l.gift?' · 책갈피 ❀':''}</button>`).join('')||'<p>첫 편지를 쓰면 답장이 와요</p>';document.querySelectorAll('[data-reply]').forEach(b=>b.onclick=()=>{if(!alive)return;const l=getProgress().village.mailbox.letters.find(l=>l.id===b.dataset.reply);if(!l)return;if(!l.read&&!transact({type:'READ_POSTCARD',id:l.id})){$('#post-result').textContent='읽음 표시를 저장하지 못했어요';return;}render();$('#post-reply').hidden=false;$('#post-reply').innerHTML=`<h3>${POST_RECIPIENTS[l.recipient].name}의 답장</h3><p>${POST_RECIPIENTS[l.recipient].reply}</p>${l.gift?'<p>케이크 고마워! 작은 꽃 책갈피를 동봉할게. ❀</p>':''}`;});}
 document.querySelectorAll('[data-recipient]').forEach(b=>b.onclick=()=>{recipient=b.dataset.recipient;render();});document.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>{template=b.dataset.template;render();});$('#post-send').onclick=()=>{if(!alive)return;const gift=$('#post-gift').checked===true,ok=transact({type:'SEND_POSTCARD',recipient,template,gift});render();$('#post-result').textContent=ok?'마을 우편함에 넣었어요. 새 답장이 도착했어요!':'저장하지 못해 편지와 선물을 보내지 않았어요';};render();return()=>{alive=false;};});}
